// The queue's state is a pure fold over the log. Replaying the same records must
// give the same state in every process, at any time. Nothing here reads the clock:
// every time in the state comes from a record.

import { loadSnapshot } from './snapshot.mjs';

export function createState() {
  return { jobs: new Map(), idem: new Map(), seq: 0, completionSeq: 0 };
}

function requeue(job, availableAt, error) {
  job.status = 'ready';
  job.availableAt = availableAt;
  job.lease = null;
  job.lastError = error ?? job.lastError;
}

// A record that acts on an attempt only counts while that attempt is the job's
// current one. Anything else is a late or repeated record, such as a reaper that
// worked from out-of-date state, and replaying it must not undo what came after.
function holdsLease(job, rec) {
  return job.status === 'leased' && job.fence === rec.fence;
}

export function applyRecord(state, rec) {
  if (rec.t === 'snapshot') {
    loadSnapshot(state, rec);
    return;
  }
  if (rec.t === 'enqueue') {
    state.seq += 1;
    state.jobs.set(rec.id, {
      id: rec.id,
      type: rec.type,
      payload: rec.payload,
      key: rec.key ?? null,
      priority: rec.priority ?? 0,
      status: 'ready',
      attempts: 0,
      fence: 0,
      maxAttempts: rec.maxAttempts,
      availableAt: rec.availableAt,
      lease: null,
      result: null,
      lastError: null,
      enqueuedAt: rec.at,
      completedAt: null,
      completionSeq: null,
      seq: state.seq,
    });
    if (rec.key) state.idem.set(rec.key, { id: rec.id, at: rec.at });
    return;
  }

  const job = state.jobs.get(rec.id);
  if (!job) return;

  switch (rec.t) {
    case 'claim':
      if (job.status !== 'ready') break;
      job.status = 'leased';
      job.attempts += 1;
      job.fence = rec.fence;
      job.lease = { worker: rec.worker, fence: rec.fence, until: rec.leaseUntil };
      break;
    case 'heartbeat':
      if (holdsLease(job, rec)) job.lease.until = rec.leaseUntil;
      break;
    case 'complete':
      if (!holdsLease(job, rec)) break;
      state.completionSeq += 1;
      job.status = 'done';
      job.lease = null;
      job.result = rec.result ?? null;
      job.completedAt = rec.at;
      job.completionSeq = state.completionSeq;
      break;
    case 'fail':
    case 'expire':
      if (!holdsLease(job, rec)) break;
      requeue(job, rec.at + rec.delayMs, rec.error);
      break;
    case 'release':
      if (!holdsLease(job, rec)) break;
      requeue(job, rec.at, rec.error);
      break;
    case 'dead':
      if (!holdsLease(job, rec)) break;
      job.status = 'dead';
      job.lease = null;
      job.lastError = rec.error ?? job.lastError;
      job.completedAt = rec.at;
      break;
    case 'cancel':
      if (job.status !== 'ready' && job.status !== 'leased') break;
      job.status = 'cancelled';
      job.lease = null;
      job.lastError = rec.error ?? job.lastError;
      job.completedAt = rec.at;
      break;
    case 'requeue':
      if (job.status !== 'dead') break;
      // The fence stays: a token is never issued twice for a job.
      job.attempts = 0;
      job.completedAt = null;
      requeue(job, rec.at, job.lastError);
      break;
    default:
      // Unknown record types come from a newer writer; ignoring them keeps old
      // tools able to read the rest of the log.
      break;
  }
}
EOF
cat > src/retention.mjs <<'EOF'
// How long finished jobs stay in the log.

const TERMINAL = new Set(['done', 'dead', 'cancelled']);

export function isTerminal(job) {
  return TERMINAL.has(job.status);
}

export function isPastRetention(job, now, config) {
  return isTerminal(job) && job.completedAt != null && now - job.completedAt >= config.retainCompletedMs;
}
EOF
cat > src/snapshot.mjs <<'EOF'
// A compacted log starts with one snapshot record holding the state it replaces.

import { isPastRetention } from './retention.mjs';

function serializeJob(job) {
  return {
    id: job.id,
    type: job.type,
    payload: job.payload,
    key: job.key,
    priority: job.priority,
    status: job.status,
    attempts: job.attempts,
    fence: job.fence,
    maxAttempts: job.maxAttempts,
    availableAt: job.availableAt,
    lease: job.lease,
    result: job.result,
    lastError: job.lastError,
    enqueuedAt: job.enqueuedAt,
    completedAt: job.completedAt,
    completionSeq: job.completionSeq,
    seq: job.seq,
  };
}

/**
 * The idempotency keys still inside their time to live. A key outlives its job, so
 * for a job that is being dropped the entry keeps what a repeat enqueue is told.
 */
function serializeKeys(state, kept, now, config) {
  const entries = [];
  for (const [key, entry] of state.idem) {
    if (now - entry.at >= config.idempotencyTtlMs) continue;
    const item = { key, id: entry.id, at: entry.at };
    if (!kept.has(entry.id)) {
      const job = state.jobs.get(entry.id);
      item.status = job?.status ?? entry.status ?? 'done';
      item.result = job ? job.result : entry.result ?? null;
    }
    entries.push(item);
  }
  return entries;
}

/** Builds the snapshot record, dropping terminal jobs past their retention. */
export function buildSnapshot(state, now, config) {
  const kept = new Set();
  const jobs = [];
  for (const job of state.jobs.values()) {
    if (isPastRetention(job, now, config)) continue;
    kept.add(job.id);
    jobs.push(serializeJob(job));
  }

  return {
    t: 'snapshot',
    at: now,
    seq: state.seq,
    completionSeq: state.completionSeq,
    jobs,
    idem: serializeKeys(state, kept, now, config),
  };
}

export function loadSnapshot(state, rec) {
  state.seq = rec.seq;
  state.completionSeq = rec.completionSeq ?? 0;
  state.jobs = new Map();
  state.idem = new Map();
  for (const job of rec.jobs) {
    state.jobs.set(job.id, {
      ...job,
      priority: job.priority ?? 0,
      attempts: job.attempts ?? 0,
      fence: job.fence ?? job.lease?.fence ?? 0,
      completionSeq: job.completionSeq ?? null,
    });
    // Older snapshots have no key list. The newest job to hold a key owns it.
    const held = job.key ? state.idem.get(job.key) : null;
    if (job.key && (!held || job.enqueuedAt >= held.at)) {
      state.idem.set(job.key, { id: job.id, at: job.enqueuedAt });
    }
  }
  for (const entry of rec.idem ?? []) {
    const { key, ...rest } = entry;
    state.idem.set(key, rest);
  }
}
